/*!40000 ALTER TABLE `support_materials` DISABLE KEYS */;
INSERT INTO `support_materials` VALUES (1,1,2,'Guía para la elaboración del perfil de tesis','Normativa','Orientaciones para estructurar correctamente el perfil y preparar el proceso de titulación.','Esta guía reúne los criterios institucionales para elaborar el perfil de tesis.\r\n\r\nIncluye recomendaciones para delimitar el tema, formular objetivos, organizar antecedentes y presentar la propuesta académica.','Instituto Superior Tecnológico \"El Libertador\"','2026-07-08','2026-07-08 00:00:00','published',0,38,118,'[\"Tesis\",\"Perfil de tesis\"]',NULL,NULL,'2026-08-09 21:28:16',1,'Publicación incorrecta',NULL,NULL,NULL,1,'2026-07-24 00:02:12','2026-08-09 21:28:16'),(2,2,2,'Formato de seguimiento de prácticas preprofesionales','Formato documental','Formato institucional para registrar actividades, horas cumplidas y evidencias de prácticas.','Documento editable destinado al seguimiento periódico de las prácticas preprofesionales.\r\n\r\nPermite registrar actividades, resultados, evidencias y validaciones del responsable institucional.','Instituto Superior Tecnológico \"El Libertador\"','2026-06-20','2026-06-20 00:00:00','published',1,4,67,'[\"Prácticas\",\"Seguimiento\",\"Evidencias\"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,134,'2026-07-24 00:02:12','2026-08-11 01:51:04'),(3,3,2,'Instructivo para proyectos PIS','Instructivo','Pasos y criterios para organizar entregables, evidencias y presentación de proyectos integradores.','Este instructivo explica el flujo recomendado para desarrollar proyectos PIS.\n\nDetalla la organización de equipos, entregables mínimos, evidencias y criterios generales de presentación.','Instituto Superior Tecnológico \"El Libertador\"','2025-12-12','2025-12-12 00:00:00','published',1,5,49,'[\"PIS\",\"Entregables\",\"Proyectos\"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-07-24 00:02:12','2026-07-29 08:05:25'),(4,4,2,'Formato de informe de vinculación','Plantilla','Plantilla editable para documentar actividades, beneficiarios, resultados e impacto comunitario.','Plantilla institucional para presentar el informe de las actividades de vinculación.\n\nOrganiza objetivos, participantes, resultados, evidencias e indicadores de impacto comunitario.','Instituto Superior Tecnológico \"El Libertador\"','2025-11-30','2025-11-30 00:00:00','published',1,6,38,'[\"Vinculación\",\"Informe\",\"Impacto\"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-24 00:02:12','2026-07-29 00:15:40'),(5,1,2,'Reglamento de uso del material académico','Reglamento','Disposiciones generales para consultar y utilizar responsablemente los recursos institucionales.','Documento informativo sobre el uso responsable del material académico institucional.\n\nResume las condiciones de consulta, atribución y distribución de los recursos disponibles.','Instituto Superior Tecnológico \"El Libertador\"','2025-05-14','2025-05-14 00:00:00','published',1,7,21,'[\"Reglamento\",\"Recursos\",\"Uso académico\"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-07-24 00:02:12','2026-07-29 00:15:40'),(9,3,NULL,'no mas','lo que séa','afeefafs','fefefefefee','Docente QA',NULL,NULL,'draft',1,NULL,0,'[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,134,134,'2026-08-11 00:27:53','2026-08-11 00:27:53');
